from __future__ import absolute_import
import re
from .base_parser import ParserBase, CommonStatCommandParser


class StatCommonParserWMP(CommonStatCommandParser):
    def __init__(self, raw_output):
        super(StatCommonParserWMP, self).__init__(raw_output)
        self._prepare_data()

    def _prepare_data(self):
        for line in self.raw_output.splitlines():
            self._prepare_each_line(line)
            self._check_channel_status(line)
            self._check_frequency(line)
            self._check_channel_type(line)
            self._check_bandwidth(line)

    def _prepare_each_line(self, line):
        antenna = re.match(
            r"\s*[TR]X(?P<number_a>\d{1,2}) Virtual Device status:", line
        )
        if antenna:
            antenna_id = "ANT{}".format(antenna.group("number_a"))
            self.antenna_id = antenna_id
        elif re.match(r".*[TR]X\d{1,2}", line) and not antenna:
            self._tx_per_antenna.setdefault(self.antenna_id, line.split())
            self._tx_list.extend(line.split())

    def _check_channel_status(self, line):
        if re.match(r"\s*Channel Status:", line):
            self._channel_status.extend(line[line.index(":") + 1:].split())

    def _check_frequency(self, line):
        if re.match(r"\s*Frequency:", line):
            self._frequency.extend(line[line.index(":") + 1:].split())

    def _check_channel_type(self, line):
        if re.match(r"\s*Channel type:", line):
            self._channel_type.extend(line[line.index(":") + 1:].split())

    def _check_bandwidth(self, line):
        if re.match(r"\s*Band\s?[Ww]idth:", line):
            self._bandwidth.extend(line[line.index(":") + 1:].split())


class TxStatWMP(StatCommonParserWMP):
    def __init__(self, raw_output):
        super(TxStatWMP, self).__init__(raw_output)

    def get_tx_per_technology(self):
        """
        Return map tx per technology (GSM, WCDMA, LTE).

        :return: tx per technology
        :rtype: dict
        """
        tx_per_tech = {}
        for technology, tx in zip(self._channel_type, self._tx_list):
            tx_per_tech.setdefault(tx[2:], technology)
        return tx_per_tech


class RxStatWMP(StatCommonParserWMP):
    def __init__(self, raw_output):
        super(RxStatWMP, self).__init__(raw_output)

    def parse_front_end_gain(self):
        """
        Parse 'rx -stat' command output.

        :return: front end gain in format {antenna: front end gain}
        :rtype: dict
        """
        antenna_gain_dict, current_antenna = {}, None
        for line in self.raw_output.splitlines():
            antenna = re.search(r"RX([\d]{1,}) Virtual Device status:", line)
            gain = re.search(r"Front End Gain\.*([\d]{1,}\.[\d]{1,})", line)
            if antenna:
                current_antenna = antenna.group(1)
            elif gain:
                antenna_gain_dict.setdefault(current_antenna, float(gain.group(1)))
        return antenna_gain_dict


class TxPowerWMP(ParserBase):
    def __init__(self, raw_output):
        super(TxPowerWMP, self).__init__(raw_output)

    def parse_tx_power(self):
        """
        Parse 'tx -power' command output.

        :return: tx power in format {tx: power}
        :rtype: dict
        """
        tx_power, pattern_re = {}, r"^TX([\d]{1,2})\s*(-?[\d]{1,}.[\d]{1,}|Power)"
        tx_iterator = re.finditer(pattern_re, self.raw_output, re.M)
        [
            tx_power.setdefault(power.group(1), "OFF")
            if power.group(2) == "Power"
            else tx_power.setdefault(power.group(1), power.group(2))
            for power in tx_iterator
        ]
        return tx_power


class RxPowerWMP(ParserBase):
    def __init__(self, raw_output):
        super(RxPowerWMP, self).__init__(raw_output)

    def parse_rx_power(self):
        """
        Parse 'tx -power' command output.

        :return: tx power in format {tx: power}
        :rtype: dict
        """
        rx_power, pattern_re = {}, r"RX([\d]{1,2})\s*(-?[\d]{1,}.[\d]{1,}|N/A)"
        rx_iterator = re.finditer(pattern_re, self.raw_output, re.M)
        [
            rx_power.setdefault(power.group(1), "OFF")
            if power.group(2) == "N/A"
            else rx_power.setdefault(power.group(1), power.group(2))
            for power in rx_iterator
        ]
        return rx_power
